// One-bit wide bit-reversed register file
module TopModule (
    input  [7:0] in,
    output [7:0] out
);
    reg [7:0] mem [0:7];
    integer i;
    always @(*) begin
        for (i = 0; i < 8; i = i + 1)
            mem[i] = in[(7 - i)];
    end
    assign out = mem[0];
endmodule

