// This is a one-line bit-reversed pipeline register, implemented as a
// stage-by-stage chain of register-to-register FULLY-CONNECTED
// combinational connections (i.e., independent of the number of bits
// of the register). This results in a critical path that is roughly
// independent of the register size, which is therefor faster than, e.g.,
// the same pipeline register implemented as a separate register-to-
// register FULLY-CONNECTED connection for each bit.
module TopModule(input [7:0] in, output [7:0] out);
  wire [7:0] stage0;
  wire [7:0] stage1;
  wire [7:0] stage2;
  wire [7:0] stage3;
  wire [7:0] stage4;
  wire [7:0] stage5;
  wire [7:0] stage6;
  wire [7:0] stage7;
  assign stage0 = in;
  assign stage1 = {stage0[0], stage0[1], stage0[2], stage0[3], stage0[4], stage0[5], stage0[6], stage0[7]};
  assign stage2 = {stage1[0], stage1[1], stage1[2], stage1[3], stage1[4], stage1[5], stage1[6], stage1[7]};
  assign stage3 = {stage2[0], stage2[1], stage2[2], stage2[3], stage2[4], stage2[5], stage2[6], stage2[7]};
  assign stage4 = {stage3[0], stage3[1], stage3[2], stage3[3], stage3[4], stage3[5], stage3[6], stage3[7]};
  assign stage5 = {stage4[0], stage4[1], stage4[2], stage4[3], stage4[4], stage4[5], stage4[6], stage4[7]};
  assign stage6 = {stage5[0], stage5[1], stage5[2], stage5[3], stage5[4], stage5[5], stage5[6], stage5[7]};
  assign stage7 = {stage6[0], stage6[1], stage6[2], stage6[3], stage6[4], stage6[5], stage6[6], stage6[7]};
  assign out = stage7;
endmodule

